    assert target["layers"] == [
        "orchestration",
        "framework",
        "world",
        "retrieval",
        "memory",
        "multi_agent",
        "evaluator",
    ]
    search_space = target["search_space"]
    assert set(search_space) == {"simulation.environments.1.data.spans"}
    assert "agent" not in search_space
    environments = manifest["simulation"]["environments"]
