def test_sdk_workflow_target_optimization_example_runs(monkeypatch, tmp_path):
    monkeypatch.setenv(
        "AGENT_LEARNING_SDK_WORKFLOW_TARGET_OPTIMIZATION_KEY",
        "real-local-sdk-workflow-target-key",
    )
    example_path = PROJECT_ROOT / "examples" / "sdk_workflow_target_optimization.py"
    spec = importlib.util.spec_from_file_location(
        "sdk_workflow_target_optimization",
        example_path,
    )
    assert spec is not None
    assert spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)

    manifest = module.build_manifest()
    assert manifest["required_env"] == [
        "AGENT_LEARNING_SDK_WORKFLOW_TARGET_OPTIMIZATION_KEY"
    ]
    assert manifest["optimization"]["threshold"] == pytest.approx(0.98)
    target = manifest["optimization"]["target"]
    assert target["metadata"]["source"] == (
        "fi.alk.optimize.build_target_optimization_manifest"
    )
    assert target["metadata"]["task_kind"] == "generic_target"
    assert target["metadata"]["optimized_surface"] == "workflow_trace_graph"
    assert target["layers"] == [
        "graph",
        "router",
        "orchestration",
        "harness",
        "evaluator",
    ]
    assert list(target["search_space"]) == [module.TARGET_PATH]
    assert "agent" not in target["search_space"]
    assert "agent.prompt" not in target["search_space"]
    environments = manifest["simulation"]["environments"]
    assert [environment["type"] for environment in environments] == [
        "workflow_trace"
    ]
    assert len(environments[0]["data"]["trace"]["nodes"]) == 1
    workflow_quality = manifest["evaluation"]["agent_report"]["config"][
        "workflow_trace_quality"
    ]
    assert workflow_quality["required_frameworks"] == module.SOURCE_FRAMEWORKS
    candidate_frameworks = sorted(
        {
            framework
            for candidate in target["search_space"][module.TARGET_PATH]
            for framework in [
                candidate.get("framework"),
                *candidate.get("source_frameworks", []),
            ]
            if framework
        }
    )
    assert candidate_frameworks == module.SOURCE_FRAMEWORKS
    strong_candidate = target["search_space"][module.TARGET_PATH][2]
    assert strong_candidate["framework"] == "langgraph"
    assert strong_candidate["source_frameworks"] == module.SOURCE_FRAMEWORKS
    assert len(strong_candidate["nodes"]) == 4
    assert len(strong_candidate["edges"]) == 3
    assert len(strong_candidate["steps"]) == 4
    assert len(strong_candidate["checkpoints"]) == 2

    output_path = tmp_path / "sdk-workflow-target-optimization-result.json"
    result = module.run(output_path)

    assert output_path.exists()
    assert json.loads(output_path.read_text(encoding="utf-8"))["status"] == "passed"
    assert result["summary"]["optimization_score"] >= 0.98
    assert result["summary"]["evaluation_score"] == pytest.approx(1.0)
    assert result["summary"]["optimizer_governance_status"] == "passed"
    assert result["summary"]["optimizer_governance_failed_check_count"] == 0
    best_history = max(
        result["optimization"]["history"],
        key=lambda item: item["score"],
    )
    assert best_history["score"] >= 0.98
    assert set(best_history["patch"]) == {module.TARGET_PATH}
    assert "agent" not in best_history["patch"]
    assert result["optimization"]["best_config"]["agent"] == manifest["agent"]
    best_environment = result["optimization"]["best_config"]["simulation"][
        "environments"
    ][0]
    assert best_environment["type"] == "workflow_trace"
    assert best_environment["data"]["trace"] == best_history["patch"][
        module.TARGET_PATH
    ]
    for metric in [
        "workflow_trace_coverage",
        "workflow_graph_quality",
        "tool_selection_accuracy",
        "artifact_coverage",
        "task_completion",
    ]:
        assert best_history["metrics"][metric] == pytest.approx(1.0)
    state = best_history["report"]["results"][0]["metadata"]["environment_state"]
    workflow = state["workflow_trace"]
    assert workflow["framework"] == "langgraph"
    assert workflow["source_frameworks"] == module.SOURCE_FRAMEWORKS
    assert workflow["summary"]["frameworks"] == [
        "crewai",
        "langgraph",
        "llamaindex",
    ]
    assert workflow["node_count"] == 4
    assert workflow["edge_count"] == 3
    assert workflow["step_count"] == 4
    assert workflow["checkpoint_count"] == 2
    assert workflow["route_decision_count"] == 1
    assert workflow["interrupt_count"] == 1
    assert workflow["replay_count"] == 1
    assert workflow["write_count"] == 1
    assert workflow["tool_names"] == ["policy_lookup"]
    assert workflow["final_state_keys"] == ["approval", "decision", "policy_result"]
    assert workflow["topology"]["entry_nodes"] == ["intake"]
    assert workflow["topology"]["terminal_nodes"] == ["finalize"]


def test_sdk_workflow_target_profile_matrix_example_runs(monkeypatch, tmp_path):
    monkeypatch.setenv(
        "AGENT_LEARNING_SDK_WORKFLOW_TARGET_PROFILE_MATRIX_KEY",
        "real-local-sdk-workflow-target-profile-matrix-key",
    )
    example_path = PROJECT_ROOT / "examples" / "sdk_workflow_target_profile_matrix.py"
    spec = importlib.util.spec_from_file_location(
        "sdk_workflow_target_profile_matrix",
        example_path,
    )
    assert spec is not None
    assert spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)

    manifests = module.build_manifests()
    assert list(manifests) == module.PROFILE_FRAMEWORKS
    for framework, manifest in manifests.items():
        assert manifest["required_env"] == [
            "AGENT_LEARNING_SDK_WORKFLOW_TARGET_PROFILE_MATRIX_KEY"
        ]
        target = manifest["optimization"]["target"]
        assert target["metadata"]["profile_framework"] == framework
        assert target["metadata"]["optimized_surface"] == "workflow_trace_profile"
        assert target["layers"] == [
            "graph",
            "router",
            "orchestration",
            "harness",
            "evaluator",
        ]
        assert list(target["search_space"]) == [module.TARGET_PATH]
        candidates = target["search_space"][module.TARGET_PATH]
        assert len(candidates) == 2
        assert candidates[0]["framework"] == framework
        assert candidates[1]["framework"] == framework
        quality = manifest["evaluation"]["agent_report"]["config"][
            "workflow_trace_quality"
        ]
        assert quality["framework"] == framework

    output_path = tmp_path / "sdk-workflow-target-profile-matrix-result.json"
    result = module.run(output_path)

    assert output_path.exists()
    serialized_result = output_path.read_text(encoding="utf-8")
    assert "real-local-sdk-workflow-target-profile-matrix-key" not in serialized_result
    assert json.loads(serialized_result)["status"] == "passed"
    assert result["kind"] == "agent-learning.workflow-target-profile-matrix.v1"
    assert result["schema_version"] == "agent-learning.cli.v1"
    assert result["status"] == "passed"
    assert result["frameworks"] == module.PROFILE_FRAMEWORKS
    assert result["summary"] == {
        "profile_count": len(module.PROFILE_FRAMEWORKS),
        "passed_profile_count": len(module.PROFILE_FRAMEWORKS),
        "failed_profiles": [],
        "all_patch_paths": [module.TARGET_PATH],
    }
    profiles = {profile["framework"]: profile for profile in result["profiles"]}
    assert set(profiles) == set(module.PROFILE_FRAMEWORKS)
    for framework, profile in profiles.items():
        assert profile["status"] == "passed"
        assert profile["workflow_framework"] == framework
        assert profile["source_export_type"] == module.SOURCE_EXPORT_TYPES[framework]
        assert profile["selected_patch_paths"] == [module.TARGET_PATH]
        assert profile["optimization_score"] >= 0.98
        assert profile["evaluation_score"] == pytest.approx(1.0)
        assert profile["best_score"] >= 0.98
        assert profile["counts"] == module.REQUIRED_COUNTS
        assert profile["tool_names"] == ["policy_lookup"]
        assert profile["tool_call_names"] == ["workflow_trace_status"]
        assert profile["final_state_keys"] == [
            "approval",
            "decision",
            "policy_result",
        ]
        assert profile["entry_nodes"] == ["intake"]
        assert profile["terminal_nodes"] == ["finalize"]
        assert profile["has_replay"] is True
        assert profile["has_interrupts"] is True
        assert profile["has_routes"] is True
        for metric in module.REQUIRED_METRICS:
            assert profile["selected_metrics"][metric] == pytest.approx(1.0)

    report_path = tmp_path / "sdk-workflow-target-profile-matrix-report.json"
    report_markdown_path = tmp_path / "sdk-workflow-target-profile-matrix-report.md"
    assert (
        main(
            [
                "report",
                str(output_path),
                "--output",
                str(report_path),
                "--markdown",
                str(report_markdown_path),
            ]
        )
        == 0
    )
    report_serialized = report_path.read_text(encoding="utf-8")
    report_markdown = report_markdown_path.read_text(encoding="utf-8")
    assert "real-local-sdk-workflow-target-profile-matrix-key" not in (
        report_serialized + report_markdown
    )
    report = json.loads(report_serialized)
    assert report["kind"] == "agent-learning.report.v1"
    assert report["status"] == "passed"
    assert "workflow_target_profile_matrix" in report["summary"]["sections"]
    workflow_card = report["report"]["workflow_target_profile_matrix"]
    assert workflow_card["kind"] == "workflow_target_profile_matrix_evidence"
    assert workflow_card["status"] == "verified"
    assert workflow_card["local_only"] is True
    assert workflow_card["requires_external_service"] is False
    assert workflow_card["target_path"] == module.TARGET_PATH
    assert workflow_card["frameworks"] == module.PROFILE_FRAMEWORKS
    assert workflow_card["profile_count"] == len(module.PROFILE_FRAMEWORKS)
    assert workflow_card["passed_profile_count"] == len(module.PROFILE_FRAMEWORKS)
    assert workflow_card["failed_profiles"] == []
    assert workflow_card["all_patch_paths"] == [module.TARGET_PATH]
    assert workflow_card["artifacts"]["replay_lock"]["local_only"] is True
    assert (
        workflow_card["artifacts"]["replay_lock"]["requires_external_service"]
        is False
    )
    for metric in module.REQUIRED_METRICS:
        assert workflow_card["metrics"][metric] == pytest.approx(1.0)
        assert workflow_card["artifacts"]["replay_lock"]["metric_thresholds"][
            metric
        ] == pytest.approx(1.0)
    card_profiles = {
        profile["framework"]: profile for profile in workflow_card["profiles"]
    }
    assert set(card_profiles) == set(module.PROFILE_FRAMEWORKS)
    for framework, profile in card_profiles.items():
        assert profile["status"] == "passed"
        assert profile["workflow_framework"] == framework
        assert profile["source_export_type"] == module.SOURCE_EXPORT_TYPES[framework]
        assert profile["selected_patch_paths"] == [module.TARGET_PATH]
        assert profile["node_count"] == module.REQUIRED_COUNTS["node_count"]
        assert profile["edge_count"] == module.REQUIRED_COUNTS["edge_count"]
        assert profile["step_count"] == module.REQUIRED_COUNTS["step_count"]
        assert profile["checkpoint_count"] == (
            module.REQUIRED_COUNTS["checkpoint_count"]
        )
        assert profile["route_decision_count"] == (
            module.REQUIRED_COUNTS["route_decision_count"]
        )
        assert profile["interrupt_count"] == module.REQUIRED_COUNTS["interrupt_count"]
        assert profile["replay_count"] == module.REQUIRED_COUNTS["replay_count"]
        assert profile["write_count"] == module.REQUIRED_COUNTS["write_count"]
        assert profile["tool_names"] == ["policy_lookup"]
        assert profile["tool_call_names"] == ["workflow_trace_status"]
        assert profile["final_state_keys"] == [
            "approval",
            "decision",
            "policy_result",
        ]
        assert profile["entry_nodes"] == ["intake"]
        assert profile["terminal_nodes"] == ["finalize"]
        assert profile["has_replay"] is True
        assert profile["has_interrupts"] is True
        assert profile["has_routes"] is True
    assert "## Workflow Target Profile Matrix" in report_markdown

    catalog = actions.action_catalog(result, source_path=output_path)
    assert catalog["kind"] == "agent-learning.actions.v1"
    assert catalog["status"] == "passed"
    workflow_actions = {
        action["id"]: action
        for action in catalog["actions"]
        if action.get("source_card_path") == "workflow_target_profile_matrix"
    }
    assert {
        "report_workflow_target_profile_matrix",
        "export_workflow_target_profile_matrix_summary",
        "export_workflow_target_profile_matrix_profiles",
        "export_workflow_target_profile_matrix_replay_lock",
    } <= set(workflow_actions)
    assert workflow_actions["export_workflow_target_profile_matrix_profiles"][
        "kind"
    ] == "download"
    assert workflow_actions["export_workflow_target_profile_matrix_profiles"][
        "artifact_ref"
    ] == "report.workflow_target_profile_matrix.artifacts.profiles"

    export_path = tmp_path / "workflow-target-profile-matrix-profiles.json"
    export_run = actions.run_action(
        result,
        "export_workflow_target_profile_matrix_profiles",
        source_path=output_path,
        cwd=tmp_path,
        artifact_output_path=export_path,
    )
    assert export_run["kind"] == "agent-learning.action-run.v1"
    assert export_run["status"] == "passed"
    assert export_run["summary"]["source_card_path"] == (
        "workflow_target_profile_matrix"
    )
    assert export_run["artifact_ref"] == (
        "report.workflow_target_profile_matrix.artifacts.profiles"
    )
    exported_profiles_serialized = export_path.read_text(encoding="utf-8")
    assert "real-local-sdk-workflow-target-profile-matrix-key" not in (
        exported_profiles_serialized
    )
    exported_profiles = {
        profile["framework"]: profile
        for profile in json.loads(exported_profiles_serialized)
    }
    assert set(exported_profiles) == set(module.PROFILE_FRAMEWORKS)
    for framework, profile in exported_profiles.items():
        assert profile["workflow_framework"] == framework
        assert profile["source_export_type"] == module.SOURCE_EXPORT_TYPES[framework]
        assert profile["selected_patch_paths"] == [module.TARGET_PATH]
        assert profile["counts"] == module.REQUIRED_COUNTS
        for metric in module.REQUIRED_METRICS:
            assert profile["selected_metrics"][metric] == pytest.approx(1.0)


def test_optimize_facade_builds_and_runs_task_world_manifest(monkeypatch):
    from fi.alk import optimize

    monkeypatch.setenv(
        "AGENT_LEARNING_SDK_TASK_WORLD_OPT_KEY",
        "real-local-sdk-task-world-opt-key",
    )

    weak_agent = {
        "type": "scripted",
        "responses": [
            {
                "content": (
                    "I inspected the refund request but did not complete the "
                    "contract transition."
                )
            }
        ],
    }
    approve_refund_tool_call = {
        "id": "approve_refund",
        "name": "apply_world_transition",
        "arguments": {"id": "approve_refund"},
    }
    approve_refund_transition = {
        "id": "approve_refund",
        "actor": "agent",
        "resource": "refund",
        "action": "approve_refund",
        "required": True,
        "preconditions": {"refund.status": "pending"},
        "effects": {"refund.status": "approved"},
        "postconditions": {"refund.status": "approved"},
        "signals": ["refund_resolution"],
    }
    world_contract = {
        "type": "world_contract",
        "data": {
            "name": "refund-world",
            "actors": ["agent", "customer"],
            "resources": ["refund"],
            "initial_state": {
                "policy": {"can_refund": True},
                "refund": {"status": "pending"},
            },
            "transitions": [],
            "invariants": [
                {
                    "id": "policy_allows_refunds",
                    "must": {"policy.can_refund": True},
                }
            ],
            "success_conditions": [
                {
                    "id": "refund_approved",
                    "must": {"refund.status": "approved"},
                }
            ],
        },
    }
    evaluation_config = {
        "task_description": "Optimize a support task world from the SDK.",
        "expected_result": "The selected agent approves the refund world contract.",
        "required_tools": ["apply_world_transition"],
        "available_tools": ["world_contract_status", "apply_world_transition"],
        "success_criteria": [
            "refund transition applied",
            "world contract terminal status is success",
        ],
        "required_world_contract": [
            "world_contract",
            "transition",
            "success_condition",
            "refund",
        ],
        "world_contract_quality": {
            "required_actors": ["agent", "customer"],
            "required_resources": ["refund"],
            "required_transitions": ["approve_refund"],
            "min_completed_transitions": 1,
            "require_all_required_transitions": True,
            "require_all_invariants_pass": True,
            "required_success_conditions": ["refund_approved"],
            "terminal_status": "success",
            "max_violation_count": 0,
            "expected_state": {"refund": {"status": "approved"}},
        },
        "metric_weights": {
            "world_contract_quality": 8.0,
            "world_contract_coverage": 3.0,
            "tool_selection_accuracy": 4.0,
            "task_completion": 1.0,
        },
    }

    manifest = optimize.build_task_optimization_manifest(
        name="sdk-task-world-optimization",
        required_env=["AGENT_LEARNING_SDK_TASK_WORLD_OPT_KEY"],
        agent_candidates=[weak_agent],
        environments=[world_contract],
        evaluation_config=evaluation_config,
        search_space={
            "agent.responses.0.tool_calls": [[], [approve_refund_tool_call]],
            "simulation.environments.0.data.transitions": [
                [],
                [approve_refund_transition],
            ],
        },
    )

    assert manifest["agent"] == weak_agent
    assert set(manifest["optimization"]["target"]["search_space"]) == {
        "agent",
        "agent.responses.0.tool_calls",
        "simulation.environments.0.data.transitions",
    }
    assert manifest["simulation"]["auto_execute_tools"] is True
    assert manifest["optimization"]["optimizer"]["max_candidates"] == 5
    assert manifest["optimization"]["target"]["layers"] == [
        "planner",
        "tools",
        "world",
        "environment",
        "evaluator",
    ]

    result = optimize.optimize_task(
        name="sdk-task-world-optimization",
        required_env=["AGENT_LEARNING_SDK_TASK_WORLD_OPT_KEY"],
        agent_candidates=[weak_agent],
        environments=[world_contract],
        evaluation_config=evaluation_config,
        search_space={
            "agent.responses.0.tool_calls": [[], [approve_refund_tool_call]],
            "simulation.environments.0.data.transitions": [
                [],
                [approve_refund_transition],
            ],
        },
        manifest_path=PROJECT_ROOT / "examples" / "sdk-task-world-optimization.json",
    )

    assert result["schema_version"] == "agent-learning.cli.v1"
    assert result["status"] == "passed"
    assert result["summary"]["optimization_score"] >= 0.95
    best_agent = result["optimization"]["best_config"]["agent"]
    assert best_agent["responses"][0]["tool_calls"][0]["name"] == (
        "apply_world_transition"
    )
    best_world = result["optimization"]["best_config"]["simulation"]["environments"][0]
    assert best_world["data"]["transitions"][0]["id"] == "approve_refund"
    best_history = max(
        result["optimization"]["history"],
        key=lambda item: item["score"],
    )
    assert {
        "agent.responses.0.tool_calls",
        "simulation.environments.0.data.transitions",
    } <= set(best_history["patch"])
    assert best_history["metrics"]["world_contract_quality"] == pytest.approx(1.0)
    assert best_history["report"]["results"][0]["metadata"]["environment_state"][
        "world_contract"
    ]["summary"]["terminal_status"] == "success"


