def test_agent_learn_release_proof_runs_selected_local_checks(tmp_path, capsys):
    from fi.alk import trinity

    output_path = tmp_path / "release-proof.json"
    exit_code = main(
        [
            "release-proof",
            "--project-root",
            str(PROJECT_ROOT),
            "--only",
            "release_check",
            "--only",
            "git_diff_check",
            "--output",
            str(output_path),
            "--quiet",
        ]
    )

    captured = capsys.readouterr()
    payload = json.loads(output_path.read_text(encoding="utf-8"))
    assert exit_code == 0
    assert captured.out == ""
    assert payload["kind"] == "agent-learning.release-proof.v1"
    assert payload["schema_version"] == "agent-learning.cli.v1"
    assert payload["status"] == "passed"
    assert payload["exit_code"] == 0
    assert payload["outputs_written"] == [str(output_path.resolve())]
    assert payload["project_root"] == str(PROJECT_ROOT)
    assert payload["required_check_ids"] == trinity.V1_RELEASE_PROOF_REQUIRED_CHECKS
    assert payload["selected_check_ids"] == ["release_check", "git_diff_check"]
    assert payload["summary"]["full_proof"] is False
    assert payload["summary"]["ready"] is False
    assert payload["summary"]["selected_check_count"] == 2
    assert payload["summary"]["unknown_selected_check_count"] == 0
    assert payload["summary"]["passed_check_count"] == 2
    assert payload["summary"]["failed_check_count"] == 0
    assert payload["summary"]["skipped_check_count"] == 5
    assert payload["handover"]["kind"] == "agent-learning.release-handover.v1"
    assert payload["handover"]["status"] == "passed"
    assert payload["handover"]["command_errors"] == []
    assert payload["handover"]["missing_files"] == []
    assert payload["handover"]["doc_errors"] == []
    checks = {check["id"]: check for check in payload["checks"]}
    assert set(checks) == set(trinity.V1_RELEASE_PROOF_REQUIRED_CHECKS)
    assert checks["release_check"]["status"] == "passed"
    assert checks["release_check"]["exit_code"] == 0
    assert checks["release_check"]["evidence"].get("planned") is not True
    assert checks["release_check"]["evidence"]["command"][:3] == [
        sys.executable,
        "-m",
        "fi.alk.cli",
    ]
    assert checks["git_diff_check"]["status"] == "passed"
    assert checks["git_diff_check"]["exit_code"] == 0
    assert checks["git_diff_check"]["evidence"].get("planned") is not True
    assert checks["git_diff_check"]["evidence"]["command"] == [
        "git",
        "diff",
        "--check",
    ]
    assert checks["pytest"]["status"] == "skipped"
    assert checks["build"]["status"] == "skipped"
    assert checks["typescript_build"]["status"] == "skipped"
    assert checks["typescript_test"]["status"] == "skipped"
    assert checks["ruff"]["status"] == "skipped"
    assert {
        finding["type"] for finding in payload["findings"]
    } == {"v1_release_proof_partial"}


def test_release_proof_command_timeout_returns_captured_evidence(monkeypatch, tmp_path):
    from fi.alk import cli as cli_module

    script = "import time; print('started', flush=True); time.sleep(30)"

    def fake_command_args(check_id, *, project_root):
        assert check_id == "pytest"
        assert project_root == tmp_path
        return [sys.executable, "-c", script]

    monkeypatch.setattr(
        cli_module,
        "_release_proof_command_args",
        fake_command_args,
    )

    result = cli_module._run_release_proof_command(
        "pytest",
        project_root=tmp_path,
        timeout_seconds=0.2,
        tail_bytes=1000,
    )

    assert result["exit_code"] == 124
    assert result["timed_out"] is True
    assert result["duration_seconds"] < 10
    assert result["stdout_tail"].strip() == "started"
    assert result["stderr_tail"] == ""
    assert result["stdout_bytes"] >= len("started\n")


def test_agent_learn_release_proof_dry_run_emits_plan(tmp_path, capsys):
    output_path = tmp_path / "release-proof-plan.json"
    exit_code = main(
        [
            "release-proof",
            "--project-root",
            str(PROJECT_ROOT),
            "--dry-run",
            "--output",
            str(output_path),
            "--quiet",
        ]
    )

    captured = capsys.readouterr()
    payload = json.loads(output_path.read_text(encoding="utf-8"))
    assert exit_code == 0
    assert captured.out == ""
    assert payload["status"] == "planned"
    assert payload["exit_code"] == 0
    assert payload["dry_run"] is True
    assert payload["summary"]["ready"] is False
    assert payload["summary"]["full_proof"] is True
    assert payload["summary"]["pending_check_count"] == 7
    assert payload["summary"]["failed_check_count"] == 0
    assert payload["summary"]["unknown_selected_check_count"] == 0
    assert {check["status"] for check in payload["checks"]} == {"pending"}
    assert payload["handover"]["status"] == "passed"
    assert payload["handover"]["command_errors"] == []
    expected_commands = {
        "release_check": [
            sys.executable,
            "-m",
            "fi.alk.cli",
            "release-check",
            "--project-root",
            str(PROJECT_ROOT),
            "--quiet",
        ],
        "ruff": [sys.executable, "-m", "ruff", "check", "."],
        "pytest": [sys.executable, "-m", "pytest", "-q"],
        "build": [sys.executable, "-m", "build"],
        "typescript_build": [
            "pnpm",
            "--dir",
            str(PROJECT_ROOT / "typescript"),
            "--filter",
            "@future-agi/agent-learning-kit",
            "build",
        ],
        "typescript_test": [
            "pnpm",
            "--dir",
            str(PROJECT_ROOT / "typescript"),
            "--filter",
            "@future-agi/agent-learning-kit",
            "test",
            "--",
            "--runInBand",
            "--silent",
        ],
        "git_diff_check": ["git", "diff", "--check"],
    }
    checks = {check["id"]: check for check in payload["checks"]}
    assert set(checks) == set(expected_commands)
    for check_id, expected_command in expected_commands.items():
        evidence = checks[check_id]["evidence"]
        assert evidence["planned"] is True
        assert evidence["reason"] == "dry run command plan"
        assert evidence["cwd"] == str(PROJECT_ROOT)
        assert evidence["command"] == expected_command
        assert evidence["exit_code"] is None
        assert evidence["timed_out"] is False
        assert evidence["stdout_bytes"] == 0
        assert evidence["stderr_bytes"] == 0
    assert {
        finding["type"] for finding in payload["findings"]
    } == {"v1_release_proof_check_pending"}


def test_release_proof_status_rejects_unknown_sdk_check_id():
    from fi.alk import trinity

    payload = trinity.release_proof_status(
        project_root=PROJECT_ROOT,
        command_results={},
        selected_check_ids=["release_check", "unknown_check"],
    )

    assert payload["status"] == "failed"
    assert payload["exit_code"] == 1
    assert payload["selected_check_ids"] == ["release_check"]
    assert payload["unknown_selected_check_ids"] == ["unknown_check"]
    assert payload["summary"]["selected_check_count"] == 1
    assert payload["summary"]["unknown_selected_check_count"] == 1
    assert {
        finding["type"] for finding in payload["findings"]
    } == {
        "v1_release_proof_check_failed",
        "v1_release_proof_partial",
        "v1_release_proof_unknown_check",
    }


def test_openenv_manifest_builds_executable_replay_candidates(monkeypatch, tmp_path):
    from fi.alk import optimize, simulate

    monkeypatch.setenv("AGENT_LEARNING_SDK_OPENENV_KEY", "local-openenv-key")
    manifest = optimize.build_openenv_optimization_manifest(
        name="sdk-openenv-environment-optimization",
        required_env=["AGENT_LEARNING_SDK_OPENENV_KEY"],
    )

    assert manifest["required_env"] == ["AGENT_LEARNING_SDK_OPENENV_KEY"]
    assert manifest["optimization"]["scoring"]["layers"] == ["openenv"]
    assert manifest["optimization"]["scoring"]["openenv_quality"][
        "min_step_count"
    ] == 2
    sources = manifest["optimization"]["target"]["metadata"]["research_sources"]
    assert {
        "https://huggingface.co/docs/openenv/index",
        "https://gymnasium.farama.org/api/env/",
    } <= {source["url"] for source in sources}

    candidates = manifest["optimization"]["target"]["search_space"][
        "simulation.environments"
    ]
    assert len(candidates) == 3
    assert [candidate[0]["type"] for candidate in candidates] == [
        "openenv",
        "openenv",
        "openenv",
    ]
    assert candidates[0][0]["data"]["metadata"]["candidate_profile"] == (
        "weak_openenv_reset_step_only"
    )
    assert candidates[-1][0]["data"]["metadata"]["candidate_profile"] == (
        "verified_openenv_replay"
    )

    environment_replay_manifest = (
        optimize.build_environment_replay_optimization_manifest(
            name="sdk-environment-replay-optimization",
            environment_replay={
                "metadata": {"compatibility_input_shape": "openenv"}
            },
            required_env=["AGENT_LEARNING_SDK_OPENENV_KEY"],
        )
    )
    assert environment_replay_manifest["required_env"] == [
        "AGENT_LEARNING_SDK_OPENENV_KEY"
    ]
    assert [
        env["type"]
        for env in environment_replay_manifest["simulation"]["environments"]
    ] == ["openenv"]
    environment_replay_candidates = environment_replay_manifest["optimization"][
        "target"
    ]["search_space"]["simulation.environments"]
    assert {
        candidate[0]["type"] for candidate in environment_replay_candidates
    } == {"openenv"}

    run_manifest = simulate.build_openenv_run_manifest(
        name="sdk-openenv-environment-run",
        required_env=["AGENT_LEARNING_SDK_OPENENV_KEY"],
    )
    assert run_manifest["version"] == "agent-learning.run.v1"
    assert [env["type"] for env in run_manifest["simulation"]["environments"]] == [
        "openenv"
    ]
    assert {
        "openenv",
        "open_env",
        "gymnasium_env",
        "environment_replay",
    } <= set(simulate.supported_manifest_environment_types())

    environment_replay_run_manifest = (
        simulate.build_environment_replay_run_manifest(
            name="sdk-environment-replay-run",
            environment_replay={
                "metadata": {"compatibility_input_shape": "gymnasium"}
            },
            required_env=["AGENT_LEARNING_SDK_OPENENV_KEY"],
        )
    )
    assert environment_replay_run_manifest["version"] == "agent-learning.run.v1"
    assert [
        env["type"]
        for env in environment_replay_run_manifest["simulation"]["environments"]
    ] == ["openenv"]

    manifest_path = tmp_path / "openenv-run.json"
    simulate.write_manifest_file(run_manifest, manifest_path)
    result = asyncio.run(simulate.run_manifest_file(manifest_path))
    assert result["status"] == "passed"
    assert result["summary"]["metric_averages"]["openenv_coverage"] == (
        pytest.approx(1.0)
    )
    assert result["summary"]["metric_averages"]["openenv_quality"] == (
        pytest.approx(1.0)
    )
    state = result["report"]["results"][0]["metadata"]["environment_state"]["openenv"]
    summary = state["summary"]
    assert summary["reset_count"] == 1
    assert summary["step_count"] == 2
    assert summary["action_route_count"] == 2
    assert summary["done"] is True
    assert summary["failure_count"] == 1
    assert summary["sandbox_enabled"] is True
    assert summary["requires_external_service"] is False

    candidate = optimize.AgentCandidate.from_config(
        {"simulation": {"environments": run_manifest["simulation"]["environments"]}},
        layers=manifest["optimization"]["target"]["layers"],
    )
    evidence = optimize.score_simulation_evidence(
        result["report"],
        manifest=manifest,
        candidate=candidate,
        config=manifest["optimization"]["scoring"],
    )
    assert evidence.score == pytest.approx(1.0)
    assert {
        component["name"]: component["score"]
        for component in evidence.metadata["simulation_evidence_score"][
            "components"
        ]
    } == {"tool_coverage": 1.0, "openenv": 1.0}


